def run_task(csv_file: str) -> dict:
    import csv
    with open(csv_file, newline='', encoding='utf-8') as fh:
        values = [float(r['brightness']) for r in csv.DictReader(fh)]
    if not values:
        raise ValueError('the CSV has no rows')
    return {'average': f'{sum(values) / len(values):.2f}'}
