def run_task(image_folder: str, threshold: int) -> dict:
    import os
    names = sorted(n for n in os.listdir(image_folder) if os.path.getsize(os.path.join(image_folder, n)) > threshold)
    return {'summary': f'{len(names)} file(s) over {threshold} bytes', 'names': names}
