def run_task(image_folder: str, output_folder: str) -> dict:
    import csv
    import os
    path = os.path.join(output_folder, 'sizes.csv')
    with open(path, 'w', newline='', encoding='utf-8') as fh:
        w = csv.writer(fh)
        w.writerow(['file', 'bytes'])
        for n in sorted(os.listdir(image_folder)):
            if n.lower().endswith('.png'):
                w.writerow([n, os.path.getsize(os.path.join(image_folder, n))])
    return {'saved': path}
```

